INSERT INTO stories (slug, title_ar, summary_ar, content_ar, cover_emoji, age_group, read_time_min, level, pages, sort_order) VALUES
('my-cat-lulu', 'قِطَّتِي لُولُو', 'قِطَّةٌ صَغِيرَةٌ تَلْعَبُ وَتَشْرَبُ وَتَنَامُ.', '<p>هَذِهِ قِطَّتِي لُولُو. لُولُو تُحِبُّ اللَّعِبَ بِالْكُرَةِ. لُولُو تَشْرَبُ الْحَلِيبَ. لُولُو تَنَامُ فِي سَرِيرِهَا. أَنَا أُحِبُّ لُولُو، وَلُولُو تُحِبُّنِي.</p>', '🐱', '3-5', 2, 1, '[{"text": "هَذِهِ قِطَّتِي لُولُو.", "scene": {"bg": "home", "items": [{"e": "🐱", "x": 50, "y": 62, "size": 140, "anim": "bounce"}]}}, {"text": "لُولُو تُحِبُّ اللَّعِبَ بِالْكُرَةِ.", "scene": {"bg": "meadow", "items": [{"e": "🐱", "x": 36, "y": 64, "size": 110, "anim": "bounce"}, {"e": "⚽", "x": 66, "y": 70, "size": 60, "anim": "spin"}]}}, {"text": "لُولُو تَشْرَبُ الْحَلِيبَ.", "scene": {"bg": "home", "items": [{"e": "🐱", "x": 40, "y": 62, "size": 110, "anim": "pulse"}, {"e": "🥛", "x": 64, "y": 70, "size": 64, "anim": "none"}]}}, {"text": "لُولُو تَنَامُ فِي سَرِيرِهَا.", "scene": {"bg": "night", "items": [{"e": "🐱", "x": 50, "y": 66, "size": 110, "anim": "float"}, {"e": "💤", "x": 64, "y": 44, "size": 50, "anim": "pulse"}]}}, {"text": "أَنَا أُحِبُّ لُولُو، وَلُولُو تُحِبُّنِي.", "scene": {"bg": "garden", "items": [{"e": "👧", "x": 38, "y": 60, "size": 120, "anim": "sway"}, {"e": "🐱", "x": 62, "y": 70, "size": 90, "anim": "bounce"}, {"e": "❤️", "x": 50, "y": 30, "size": 50, "anim": "pulse"}]}}]'::jsonb, 100),
('sun-and-moon', 'الشَّمْسُ وَالْقَمَرُ', 'فِي الصَّبَاحِ شَمْسٌ، وَفِي اللَّيْلِ قَمَرٌ.', '<p>فِي الصَّبَاحِ تَطْلُعُ الشَّمْسُ. نَذْهَبُ إِلَى الْمَدْرَسَةِ. فِي اللَّيْلِ يَطْلُعُ الْقَمَرُ. نَنَامُ وَنَحْلُمُ بِالنُّجُومِ. شُكْرًا يَا شَمْسُ، شُكْرًا يَا قَمَرُ.</p>', '🌞', '3-5', 2, 1, '[{"text": "فِي الصَّبَاحِ تَطْلُعُ الشَّمْسُ.", "scene": {"bg": "sky", "items": [{"e": "🌞", "x": 50, "y": 48, "size": 150, "anim": "pulse"}]}}, {"text": "نَذْهَبُ إِلَى الْمَدْرَسَةِ.", "scene": {"bg": "village", "items": [{"e": "🏫", "x": 72, "y": 58, "size": 110, "anim": "none"}, {"e": "🧒", "x": 36, "y": 66, "size": 90, "anim": "walk"}]}}, {"text": "فِي اللَّيْلِ يَطْلُعُ الْقَمَرُ.", "scene": {"bg": "night", "items": [{"e": "🌕", "x": 50, "y": 40, "size": 130, "anim": "float"}, {"e": "⭐", "x": 22, "y": 30, "size": 40, "anim": "pulse"}]}}, {"text": "نَنَامُ وَنَحْلُمُ بِالنُّجُومِ.", "scene": {"bg": "night", "items": [{"e": "😴", "x": 50, "y": 66, "size": 100, "anim": "float"}, {"e": "⭐", "x": 30, "y": 30, "size": 44, "anim": "pulse"}, {"e": "🌟", "x": 70, "y": 34, "size": 50, "anim": "pulse"}]}}, {"text": "شُكْرًا يَا شَمْسُ، شُكْرًا يَا قَمَرُ.", "scene": {"bg": "sky", "items": [{"e": "🌞", "x": 30, "y": 46, "size": 110, "anim": "pulse"}, {"e": "🌛", "x": 70, "y": 46, "size": 110, "anim": "sway"}]}}]'::jsonb, 101),
('little-duck-swims', 'الْبَطَّةُ الصَّغِيرَةُ تَسْبَحُ', 'بَطَّةٌ صَغِيرَةٌ تَخَافُ مِنَ الْمَاءِ، فَمَاذَا فَعَلَتْ؟', '<p>كَانَتْ بَطَّةٌ صَغِيرَةٌ تَخَافُ مِنَ الْمَاءِ. قَالَتْ لَهَا أُمُّهَا: لَا تَخَافِي يَا صَغِيرَتِي، أَنَا مَعَكِ. وَضَعَتِ الْبَطَّةُ الصَّغِيرَةُ قَدَمَهَا فِي الْمَاءِ، فَوَجَدَتْهُ لَطِيفًا. حَرَّكَتْ قَدَمَيْهَا مَرَّةً بَعْدَ مَرَّةٍ، فَسَبَحَتْ! فَرِحَتِ الْبَطَّةُ وَقَالَتْ: الْخَوْفُ يَذْهَبُ عِنْدَمَا نُحَاوِلُ.</p>', '🦆', '6-8', 3, 2, '[{"text": "كَانَتْ بَطَّةٌ صَغِيرَةٌ تَخَافُ مِنَ الْمَاءِ.", "scene": {"bg": "sea", "items": [{"e": "🐤", "x": 30, "y": 40, "size": 80, "anim": "sway"}]}}, {"text": "قَالَتْ لَهَا أُمُّهَا: لَا تَخَافِي يَا صَغِيرَتِي، أَنَا مَعَكِ.", "scene": {"bg": "sea", "items": [{"e": "🦆", "x": 56, "y": 68, "size": 110, "anim": "float"}, {"e": "🐤", "x": 30, "y": 42, "size": 70, "anim": "bounce"}]}}, {"text": "وَضَعَتِ الْبَطَّةُ الصَّغِيرَةُ قَدَمَهَا فِي الْمَاءِ، فَوَجَدَتْهُ لَطِيفًا.", "scene": {"bg": "sea", "items": [{"e": "🐤", "x": 42, "y": 62, "size": 80, "anim": "pulse"}, {"e": "💧", "x": 54, "y": 74, "size": 36, "anim": "bounce"}]}}, {"text": "حَرَّكَتْ قَدَمَيْهَا مَرَّةً بَعْدَ مَرَّةٍ، فَسَبَحَتْ!", "scene": {"bg": "sea", "items": [{"e": "🐤", "x": 50, "y": 68, "size": 80, "anim": "walk"}, {"e": "🦆", "x": 76, "y": 70, "size": 90, "anim": "float"}]}}, {"text": "فَرِحَتِ الْبَطَّةُ وَقَالَتْ: الْخَوْفُ يَذْهَبُ عِنْدَمَا نُحَاوِلُ.", "scene": {"bg": "sea", "items": [{"e": "🐤", "x": 40, "y": 66, "size": 90, "anim": "bounce"}, {"e": "🦆", "x": 64, "y": 68, "size": 100, "anim": "float"}, {"e": "⭐", "x": 50, "y": 34, "size": 44, "anim": "spin"}]}}]'::jsonb, 102),
('salma-lemon-tree', 'سَلْمَى وَشَجَرَةُ اللَّيْمُونِ', 'زَرَعَتْ سَلْمَى بِذْرَةً، وَتَعَلَّمَتِ الصَّبْرَ.', '<p>زَرَعَتْ سَلْمَى بِذْرَةً صَغِيرَةً فِي حَدِيقَةِ الْبَيْتِ. كَانَتْ تَسْقِيهَا كُلَّ يَوْمٍ، لَكِنَّ الْبِذْرَةَ لَمْ تَظْهَرْ. قَالَ جَدُّهَا: النَّبَاتُ يَحْتَاجُ إِلَى الْمَاءِ وَالشَّمْسِ وَالصَّبْرِ. وَبَعْدَ أَيَّامٍ ظَهَرَتْ وَرَقَةٌ خَضْرَاءُ صَغِيرَةٌ. كَبِرَتِ الشَّجَرَةُ سَنَةً بَعْدَ سَنَةٍ، وَأَعْطَتْ لَيْمُونًا كَثِيرًا. وَزَّعَتْ سَلْمَى اللَّيْمُونَ عَلَى جِيرَانِهَا، فَفَرِحُوا كَثِيرًا.</p>', '🍋', '6-8', 3, 2, '[{"text": "زَرَعَتْ سَلْمَى بِذْرَةً صَغِيرَةً فِي حَدِيقَةِ الْبَيْتِ.", "scene": {"bg": "garden", "items": [{"e": "👧", "x": 40, "y": 58, "size": 110, "anim": "sway"}, {"e": "🌰", "x": 60, "y": 80, "size": 36, "anim": "none"}]}}, {"text": "كَانَتْ تَسْقِيهَا كُلَّ يَوْمٍ، لَكِنَّ الْبِذْرَةَ لَمْ تَظْهَرْ.", "scene": {"bg": "garden", "items": [{"e": "👧", "x": 36, "y": 58, "size": 100, "anim": "none"}, {"e": "🚿", "x": 58, "y": 50, "size": 56, "anim": "sway"}, {"e": "💧", "x": 60, "y": 72, "size": 30, "anim": "bounce"}]}}, {"text": "قَالَ جَدُّهَا: النَّبَاتُ يَحْتَاجُ إِلَى الْمَاءِ وَالشَّمْسِ وَالصَّبْرِ.", "scene": {"bg": "meadow", "items": [{"e": "👴", "x": 60, "y": 58, "size": 110, "anim": "sway"}, {"e": "👧", "x": 34, "y": 64, "size": 90, "anim": "none"}]}}, {"text": "وَبَعْدَ أَيَّامٍ ظَهَرَتْ وَرَقَةٌ خَضْرَاءُ صَغِيرَةٌ.", "scene": {"bg": "garden", "items": [{"e": "🌱", "x": 50, "y": 74, "size": 80, "anim": "pulse"}, {"e": "👧", "x": 26, "y": 60, "size": 90, "anim": "bounce"}]}}, {"text": "كَبِرَتِ الشَّجَرَةُ سَنَةً بَعْدَ سَنَةٍ، وَأَعْطَتْ لَيْمُونًا كَثِيرًا.", "scene": {"bg": "garden", "items": [{"e": "🌳", "x": 50, "y": 52, "size": 170, "anim": "sway"}, {"e": "🍋", "x": 42, "y": 44, "size": 34, "anim": "pulse"}, {"e": "🍋", "x": 58, "y": 38, "size": 34, "anim": "pulse"}]}}, {"text": "وَزَّعَتْ سَلْمَى اللَّيْمُونَ عَلَى جِيرَانِهَا، فَفَرِحُوا كَثِيرًا.", "scene": {"bg": "village", "items": [{"e": "👧", "x": 34, "y": 62, "size": 90, "anim": "walk"}, {"e": "🧺", "x": 50, "y": 72, "size": 50, "anim": "none"}, {"e": "👵", "x": 70, "y": 62, "size": 90, "anim": "sway"}]}}]'::jsonb, 103),
('trip-on-the-nile', 'رحلة على النيل', 'يوسف يركب قاربًا مع أبيه ويصبح صديقًا للنيل.', '<p>في يوم الجمعة، ركب يوسف مع أبيه قاربًا صغيرًا على نهر النيل. رأى يوسف طيورًا بيضاء تطير فوق الماء، ورأى النخيل على الشاطئ. سأل يوسف: يا أبي، من أين يأتي كل هذا الماء؟ قال الأب: يأتي النيل من قلب أفريقيا، ويسير آلاف الكيلومترات حتى يصل إلينا. ثم قال الأب: لذلك يجب أن نحافظ على النيل نظيفًا، فلا نرمي فيه شيئًا. رأى يوسف زجاجة فارغة تطفو على الماء، فالتقطها ووضعها في الكيس. ابتسم الأب وقال: أنت صديق النيل يا يوسف.</p>', '⛵', '6-8', 4, 3, '[{"text": "في يوم الجمعة، ركب يوسف مع أبيه قاربًا صغيرًا على نهر النيل.", "scene": {"bg": "sea", "items": [{"e": "⛵", "x": 50, "y": 62, "size": 130, "anim": "float"}]}}, {"text": "رأى يوسف طيورًا بيضاء تطير فوق الماء، ورأى النخيل على الشاطئ.", "scene": {"bg": "sea", "items": [{"e": "🕊️", "x": 30, "y": 30, "size": 56, "anim": "float"}, {"e": "🕊️", "x": 60, "y": 22, "size": 44, "anim": "float"}, {"e": "🌴", "x": 86, "y": 50, "size": 100, "anim": "sway"}, {"e": "⛵", "x": 40, "y": 70, "size": 80, "anim": "float"}]}}, {"text": "سأل يوسف: يا أبي، من أين يأتي كل هذا الماء؟ قال الأب: يأتي النيل من قلب أفريقيا، ويسير آلاف الكيلومترات حتى يصل إلينا.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 36, "y": 56, "size": 90, "anim": "bounce"}, {"e": "👨", "x": 62, "y": 54, "size": 100, "anim": "none"}, {"e": "🌍", "x": 50, "y": 22, "size": 56, "anim": "spin"}]}}, {"text": "ثم قال الأب: لذلك يجب أن نحافظ على النيل نظيفًا، فلا نرمي فيه شيئًا.", "scene": {"bg": "sea", "items": [{"e": "👨", "x": 50, "y": 56, "size": 110, "anim": "sway"}, {"e": "💙", "x": 70, "y": 30, "size": 50, "anim": "pulse"}]}}, {"text": "رأى يوسف زجاجة فارغة تطفو على الماء، فالتقطها ووضعها في الكيس.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 36, "y": 56, "size": 90, "anim": "none"}, {"e": "🧴", "x": 62, "y": 72, "size": 50, "anim": "float"}, {"e": "🛍️", "x": 22, "y": 66, "size": 50, "anim": "none"}]}}, {"text": "ابتسم الأب وقال: أنت صديق النيل يا يوسف.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 40, "y": 58, "size": 90, "anim": "bounce"}, {"e": "👨", "x": 62, "y": 56, "size": 100, "anim": "none"}, {"e": "♻️", "x": 50, "y": 26, "size": 50, "anim": "spin"}]}}]'::jsonb, 104),
('library-treasure', 'الكنز في المكتبة', 'عمر يبحث عن كنز في مكتبة المدرسة، فماذا وجد؟', '<p>سمع عمر أن في مكتبة المدرسة كنزًا، فقرر أن يبحث عنه. فتّش عمر بين الرفوف، فلم يجد ذهبًا ولا جواهر، بل وجد كتبًا كثيرة. فتح كتابًا عن البحار، فرأى الحيتان الكبيرة والأسماك الملونة. ثم فتح كتابًا عن الفضاء، فطار بخياله إلى القمر والنجوم. قالت أمينة المكتبة: هل وجدت الكنز يا عمر؟ ضحك عمر وقال: نعم، الكنز هو الكتب!</p>', '📚', '6-8', 4, 3, '[{"text": "سمع عمر أن في مكتبة المدرسة كنزًا، فقرر أن يبحث عنه.", "scene": {"bg": "home", "items": [{"e": "🧒", "x": 36, "y": 60, "size": 100, "anim": "bounce"}, {"e": "🔍", "x": 60, "y": 46, "size": 60, "anim": "sway"}]}}, {"text": "فتّش عمر بين الرفوف، فلم يجد ذهبًا ولا جواهر، بل وجد كتبًا كثيرة.", "scene": {"bg": "home", "items": [{"e": "📚", "x": 30, "y": 60, "size": 90, "anim": "none"}, {"e": "📚", "x": 70, "y": 60, "size": 90, "anim": "none"}, {"e": "🧒", "x": 50, "y": 64, "size": 90, "anim": "sway"}]}}, {"text": "فتح كتابًا عن البحار، فرأى الحيتان الكبيرة والأسماك الملونة.", "scene": {"bg": "sea", "items": [{"e": "🐋", "x": 40, "y": 72, "size": 120, "anim": "float"}, {"e": "🐠", "x": 72, "y": 80, "size": 50, "anim": "walk"}]}}, {"text": "ثم فتح كتابًا عن الفضاء، فطار بخياله إلى القمر والنجوم.", "scene": {"bg": "night", "items": [{"e": "🚀", "x": 40, "y": 50, "size": 100, "anim": "float"}, {"e": "🌟", "x": 72, "y": 34, "size": 70, "anim": "spin"}]}}, {"text": "قالت أمينة المكتبة: هل وجدت الكنز يا عمر؟ ضحك عمر وقال: نعم، الكنز هو الكتب!", "scene": {"bg": "home", "items": [{"e": "👩‍🏫", "x": 64, "y": 58, "size": 100, "anim": "none"}, {"e": "🧒", "x": 36, "y": 62, "size": 90, "anim": "bounce"}, {"e": "📖", "x": 50, "y": 34, "size": 60, "anim": "pulse"}]}}]'::jsonb, 105),
('the-little-inventor', 'المخترعة الصغيرة', 'مريم تصنع جهازًا يساعد جدتها، وتتعلم أن المحاولة طريق النجاح.', '<p>كانت مريم تحب أن تفك الأشياء القديمة لتعرف كيف تعمل، وكانت تحلم أن تصنع اختراعًا يساعد الناس. لاحظت مريم أن جدتها تنسى أن تسقي نباتاتها، فتذبل الأوراق وتحزن الجدة. قررت مريم أن تصنع جهازًا صغيرًا يذكّر جدتها بسقي النباتات، فجمعت زجاجة فارغة وأنبوبًا وجرسًا قديمًا. في المحاولة الأولى سقط الماء على الأرض، وفي الثانية لم يرنّ الجرس. شعرت مريم بالضيق، لكنها لم تستسلم. وفي المحاولة الثالثة رنّ الجرس في موعده، ونزل الماء قطرة قطرة على التربة. ابتسمت الجدة وقالت: كل محاولة تقربنا من النجاح يا مريم. ومنذ ذلك اليوم بقيت النباتات خضراء.</p>', '🔧', '9-12', 5, 4, '[{"text": "كانت مريم تحب أن تفك الأشياء القديمة لتعرف كيف تعمل، وكانت تحلم أن تصنع اختراعًا يساعد الناس.", "scene": {"bg": "home", "items": [{"e": "👧", "x": 36, "y": 60, "size": 100, "anim": "sway"}, {"e": "⚙️", "x": 64, "y": 40, "size": 60, "anim": "spin"}, {"e": "🔧", "x": 64, "y": 70, "size": 50, "anim": "none"}]}}, {"text": "لاحظت مريم أن جدتها تنسى أن تسقي نباتاتها، فتذبل الأوراق وتحزن الجدة.", "scene": {"bg": "garden", "items": [{"e": "👵", "x": 60, "y": 58, "size": 100, "anim": "none"}, {"e": "🥀", "x": 34, "y": 72, "size": 60, "anim": "sway"}]}}, {"text": "قررت مريم أن تصنع جهازًا صغيرًا يذكّر جدتها بسقي النباتات، فجمعت زجاجة فارغة وأنبوبًا وجرسًا قديمًا.", "scene": {"bg": "home", "items": [{"e": "👧", "x": 30, "y": 60, "size": 90, "anim": "bounce"}, {"e": "🧴", "x": 52, "y": 66, "size": 50, "anim": "none"}, {"e": "🔔", "x": 72, "y": 60, "size": 50, "anim": "sway"}]}}, {"text": "في المحاولة الأولى سقط الماء على الأرض، وفي الثانية لم يرنّ الجرس. شعرت مريم بالضيق، لكنها لم تستسلم.", "scene": {"bg": "home", "items": [{"e": "😟", "x": 40, "y": 56, "size": 90, "anim": "none"}, {"e": "💦", "x": 66, "y": 74, "size": 50, "anim": "bounce"}]}}, {"text": "وفي المحاولة الثالثة رنّ الجرس في موعده، ونزل الماء قطرة قطرة على التربة.", "scene": {"bg": "garden", "items": [{"e": "🔔", "x": 40, "y": 40, "size": 70, "anim": "sway"}, {"e": "💧", "x": 60, "y": 60, "size": 36, "anim": "bounce"}, {"e": "🌱", "x": 60, "y": 80, "size": 56, "anim": "pulse"}]}}, {"text": "ابتسمت الجدة وقالت: كل محاولة تقربنا من النجاح يا مريم. ومنذ ذلك اليوم بقيت النباتات خضراء.", "scene": {"bg": "garden", "items": [{"e": "👵", "x": 62, "y": 58, "size": 100, "anim": "sway"}, {"e": "👧", "x": 38, "y": 62, "size": 90, "anim": "bounce"}, {"e": "🌻", "x": 84, "y": 66, "size": 60, "anim": "sway"}]}}]'::jsonb, 106),
('my-new-friend', 'صديقي الجديد', 'آدم طالب جديد يتكلم ببطء، والفصل كله يتعلم معنى الصداقة.', '<p>في أول يوم من العام الدراسي، دخل الفصل طالب جديد اسمه آدم، وجلس وحده في آخر الصف. كان آدم يتكلم ببطء ويتلعثم أحيانًا، فضحك بعض الأولاد، واحمرّ وجهه خجلًا. في الفسحة، رأته ليلى يجلس تحت الشجرة، فاقتربت منه وقالت: هل تحب أن تلعب معنا؟ لعب آدم معهم الكرة، واكتشفوا أنه حارس مرمى ماهر يمسك الكرات الصعبة بسهولة. في اليوم التالي جلس الجميع بجانب آدم، وصاروا ينتظرونه حتى ينهي كلامه دون أن يقاطعوه. وتعلم الأطفال أن لكل واحد منا طريقته في الكلام، وأن الصداقة تبدأ بكلمة طيبة.</p>', '🤝', '9-12', 5, 4, '[{"text": "في أول يوم من العام الدراسي، دخل الفصل طالب جديد اسمه آدم، وجلس وحده في آخر الصف.", "scene": {"bg": "village", "items": [{"e": "🏫", "x": 70, "y": 54, "size": 120, "anim": "none"}, {"e": "🧒", "x": 34, "y": 66, "size": 80, "anim": "none"}]}}, {"text": "كان آدم يتكلم ببطء ويتلعثم أحيانًا، فضحك بعض الأولاد، واحمرّ وجهه خجلًا.", "scene": {"bg": "home", "items": [{"e": "😳", "x": 50, "y": 56, "size": 110, "anim": "pulse"}]}}, {"text": "في الفسحة، رأته ليلى يجلس تحت الشجرة، فاقتربت منه وقالت: هل تحب أن تلعب معنا؟", "scene": {"bg": "garden", "items": [{"e": "🌳", "x": 70, "y": 50, "size": 150, "anim": "sway"}, {"e": "🧒", "x": 66, "y": 70, "size": 70, "anim": "none"}, {"e": "👧", "x": 34, "y": 66, "size": 80, "anim": "walk"}]}}, {"text": "لعب آدم معهم الكرة، واكتشفوا أنه حارس مرمى ماهر يمسك الكرات الصعبة بسهولة.", "scene": {"bg": "meadow", "items": [{"e": "🥅", "x": 76, "y": 62, "size": 110, "anim": "none"}, {"e": "🧤", "x": 70, "y": 54, "size": 50, "anim": "bounce"}, {"e": "⚽", "x": 40, "y": 70, "size": 50, "anim": "spin"}]}}, {"text": "في اليوم التالي جلس الجميع بجانب آدم، وصاروا ينتظرونه حتى ينهي كلامه دون أن يقاطعوه.", "scene": {"bg": "home", "items": [{"e": "🧒", "x": 50, "y": 60, "size": 90, "anim": "bounce"}, {"e": "👧", "x": 28, "y": 62, "size": 80, "anim": "none"}, {"e": "👦", "x": 72, "y": 62, "size": 80, "anim": "none"}]}}, {"text": "وتعلم الأطفال أن لكل واحد منا طريقته في الكلام، وأن الصداقة تبدأ بكلمة طيبة.", "scene": {"bg": "sky", "items": [{"e": "🤝", "x": 50, "y": 50, "size": 120, "anim": "pulse"}, {"e": "💛", "x": 30, "y": 30, "size": 44, "anim": "float"}, {"e": "💚", "x": 70, "y": 30, "size": 44, "anim": "float"}]}}]'::jsonb, 107)
